import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';
import { 
  Heart, 
  MessageCircle, 
  Share2, 
  Users,
  Briefcase,
  Trophy,
  TrendingUp,
  Calendar,
  Award,
  Bell,
  Trash2
} from 'lucide-react';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const { user } = useAuth();
  const [posts, setPosts] = useState([]);
  const [recentJobs, setRecentJobs] = useState([]);
  const [recentCompetitions, setRecentCompetitions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newPost, setNewPost] = useState('');
  const [showCreatePost, setShowCreatePost] = useState(false);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [postsRes, jobsRes, competitionsRes] = await Promise.all([
        axios.get('/api/posts?limit=5'),
        axios.get('/api/jobs?limit=3'),
        axios.get('/api/competitions?limit=3')
      ]);

      setPosts(postsRes.data.posts || []);
      setRecentJobs(jobsRes.data.jobs || []);
      setRecentCompetitions(competitionsRes.data.competitions || []);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    if (!newPost.trim()) return;

    try {
      const response = await axios.post('/api/posts', {
        description: newPost
      });

      setPosts([response.data, ...posts]);
      setNewPost('');
      setShowCreatePost(false);
      toast.success('Post created successfully!');
    } catch (error) {
      toast.error('Failed to create post');
    }
  };

  const handleLikePost = async (postId) => {
    try {
      const response = await axios.put(`/api/posts/${postId}/like`);
      setPosts(posts.map(post => 
        post._id === postId ? response.data : post
      ));
    } catch (error) {
      toast.error('Failed to like post');
    }
  };

  const handleDeletePost = async (postId) => {
    if (!window.confirm('Are you sure you want to delete this post?')) {
      return;
    }

    try {
      await axios.delete(`/api/posts/${postId}`);
      setPosts(posts.filter(post => post._id !== postId));
      toast.success('Post deleted successfully!');
    } catch (error) {
      toast.error('Failed to delete post');
    }
  };

  const formatDate = (date) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-centurion-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Welcome Section */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900">
          Welcome back, {user?.name}!
        </h1>
        <p className="text-gray-600 mt-2">
          {user?.role === 'student' && 'Discover opportunities and showcase your talents'}
          {user?.role === 'faculty' && 'Manage competitions and engage with students'}
          {user?.role === 'recruiter' && 'Find talented students for your opportunities'}
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Create Post Section */}
          {!showCreatePost ? (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
              <button
                onClick={() => setShowCreatePost(true)}
                className="w-full text-left p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors flex items-center space-x-3"
              >
                <div className="w-10 h-10 bg-centurion-600 rounded-full flex items-center justify-center">
                  <span className="text-white font-medium">
                    {user?.name?.charAt(0).toUpperCase()}
                  </span>
                </div>
                <span className="text-gray-500">Share your achievements, projects, or thoughts...</span>
              </button>
            </div>
          ) : (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <form onSubmit={handleCreatePost}>
                <textarea
                  value={newPost}
                  onChange={(e) => setNewPost(e.target.value)}
                  placeholder="What's on your mind?"
                  className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-centurion-500 focus:border-transparent resize-none"
                  rows="4"
                  autoFocus
                />
                <div className="flex justify-between items-center mt-4">
                  <button
                    type="button"
                    onClick={() => {
                      setShowCreatePost(false);
                      setNewPost('');
                    }}
                    className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={!newPost.trim()}
                    className="px-6 py-2 bg-centurion-600 text-white rounded-lg hover:bg-centurion-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                  >
                    Post
                  </button>
                </div>
              </form>
            </div>
          )}

          {/* Posts Feed */}
          <div className="space-y-6">
            <h2 className="text-xl font-semibold text-gray-900 flex items-center">
              <TrendingUp className="h-5 w-5 mr-2" />
              Recent Posts
            </h2>

            {posts.length === 0 ? (
              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-8 text-center">
                <p className="text-gray-500">No posts yet. Be the first to share something!</p>
              </div>
            ) : (
              posts.map((post) => (
                <div key={post._id} className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                  <div className="flex items-start space-x-3">
                    <div className="w-10 h-10 bg-centurion-600 rounded-full flex items-center justify-center">
                      <span className="text-white font-medium">
                        {post.user?.name?.charAt(0).toUpperCase()}
                      </span>
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center space-x-2">
                        <h3 className="font-medium text-gray-900">{post.user?.name}</h3>
                        <span className="text-sm text-gray-500 capitalize">{post.user?.role}</span>
                        <span className="text-sm text-gray-400">•</span>
                        <span className="text-sm text-gray-400">{formatDate(post.createdAt)}</span>
                      </div>
                      <p className="text-gray-700 mt-2">{post.description}</p>

                      <div className="flex items-center space-x-6 mt-4 pt-4 border-t border-gray-100">
                        <button
                          onClick={() => handleLikePost(post._id)}
                          className={`flex items-center space-x-2 text-sm transition-colors ${
                            post.likes?.some(like => like.user === user?.id)
                              ? 'text-red-600 hover:text-red-700'
                              : 'text-gray-500 hover:text-red-600'
                          }`}
                        >
                          <Heart className={`h-4 w-4 ${
                            post.likes?.some(like => like.user === user?.id) ? 'fill-current' : ''
                          }`} />
                          <span>{post.likes?.length || 0}</span>
                        </button>
                        <button className="flex items-center space-x-2 text-sm text-gray-500 hover:text-gray-700 transition-colors">
                          <MessageCircle className="h-4 w-4" />
                          <span>{post.comments?.length || 0}</span>
                        </button>
                        <button className="flex items-center space-x-2 text-sm text-gray-500 hover:text-gray-700 transition-colors">
                          <Share2 className="h-4 w-4" />
                          <span>Share</span>
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Quick Stats */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Quick Overview</h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <Briefcase className="h-4 w-4 text-centurion-600" />
                  <span className="text-sm text-gray-600">Available Jobs</span>
                </div>
                <span className="font-medium text-gray-900">{recentJobs.length}</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <Trophy className="h-4 w-4 text-centurion-600" />
                  <span className="text-sm text-gray-600">Active Competitions</span>
                </div>
                <span className="font-medium text-gray-900">{recentCompetitions.length}</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <Users className="h-4 w-4 text-centurion-600" />
                  <span className="text-sm text-gray-600">Your Skills</span>
                </div>
                <span className="font-medium text-gray-900">{user?.skills?.length || 0}</span>
              </div>
            </div>
          </div>

          {/* Recent Jobs */}
          {recentJobs.length > 0 && (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                <Briefcase className="h-5 w-5 mr-2" />
                Recent Opportunities
              </h3>
              <div className="space-y-3">
                {recentJobs.slice(0, 3).map((job) => (
                  <div key={job._id} className="border-l-4 border-centurion-500 pl-3">
                    <h4 className="font-medium text-gray-900 text-sm">{job.title}</h4>
                    <p className="text-xs text-gray-600">{job.company}</p>
                    <p className="text-xs text-gray-500 capitalize">{job.type}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Recent Competitions */}
          {recentCompetitions.length > 0 && (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                <Trophy className="h-5 w-5 mr-2" />
                Upcoming Competitions
              </h3>
              <div className="space-y-3">
                {recentCompetitions.slice(0, 3).map((competition) => (
                  <div key={competition._id} className="border-l-4 border-yellow-500 pl-3">
                    <h4 className="font-medium text-gray-900 text-sm">{competition.title}</h4>
                    <div className="flex items-center space-x-2 mt-1">
                      <Calendar className="h-3 w-3 text-gray-400" />
                      <p className="text-xs text-gray-600">{formatDate(competition.date)}</p>
                    </div>
                    <p className="text-xs text-gray-500 capitalize">{competition.category}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
